$chat=New-Object Windows.Forms.TextBox;$chat.Multiline=$true;$chat.ReadOnly=$true;$chat.ScrollBars='Vertical';$chat.Location='42,120';$chat.Size='850,315';$chat.BackColor=[Drawing.SystemColors]::Window;$chat.ForeColor=[Drawing.SystemColors]::WindowText;$chat.Font=New-Object Drawing.Font('Segoe UI',11);$chat.Text="MODEL FORGE`r`n`r`nWhat would you like to build?`r`n`r`nExample: A small forest cat with warm orange fur, a friendly face, and a simple low-poly game style.";$form.Controls.Add($chat)
