$status=New-Object Windows.Forms.Label;$status.Text='Ready when you are';$status.Location='44,560';$status.Size='500,28';$status.ForeColor=[Drawing.SystemColors]::ControlText;$status.BackColor=[Drawing.SystemColors]::Control;$status.Font=New-Object Drawing.Font('Segoe UI Semibold',10);$form.Controls.Add($status)
