$log=New-Object Windows.Forms.TextBox;$log.Multiline=$true;$log.ReadOnly=$true;$log.ScrollBars='Vertical';$log.Location='42,605';$log.Size='850,72';$log.BackColor=[Drawing.SystemColors]::Window;$log.ForeColor=[Drawing.SystemColors]::WindowText;$log.Font=New-Object Drawing.Font('Consolas',9);$form.Controls.Add($log)
$progress=New-Object Windows.Forms.ProgressBar;$progress.Location='42,585';$progress.Size='850,12';$progress.Style='Marquee';$progress.MarqueeAnimationSpeed=25;$form.Controls.Add($progress)
$script:activeLog=$null;$script:logOffset=0;$script:activeProcess=$null;$script:activeJob=$null;$script:totalJobs=0;$script:completedJobs=0
$uiTimer=New-Object Windows.Forms.Timer;$uiTimer.Interval=250;$uiTimer.add_Tick({if($script:activeLog -and (Test-Path $script:activeLog)){$text=[IO.File]::ReadAllText($script:activeLog);if($text.Length -gt $script:logOffset){$chunk=$text.Substring($script:logOffset);$log.AppendText($chunk);$script:logOffset=$text.Length;$log.SelectionStart=$log.Text.Length;$log.ScrollToCaret();if($chunk -match 'stage 1|infer|Generating'){$status.Text='Job progress: generating image...'}elseif($chunk -match 'background removal'){$status.Text='Job progress: removing background...'}elseif($chunk -match 'stage 3|trellis-cli'){$status.Text='Job progress: building 3D model on Vulkan...'}elseif($chunk -match 'transit|upscaling'){$status.Text='Job progress: preparing Unity files...'}}};if($script:activeProcess -and $script:activeProcess.HasExited){$r=$script:activeProcess; $j=$script:activeJob; $script:activeProcess=$null;$script:activeJob=$null;$script:busy=$false;$script:completedJobs++;$progress.Style='Blocks';$progress.Value=100;if($r.ExitCode -eq 0){$status.Text='Complete - image and 3D model ready';$queue.Text=('Build queue - complete {0}/{1}' -f $script:completedJobs,$script:totalJobs);$chat.AppendText("`r`n`r`nSYSTEM`r`nComplete. Outputs: $($j.Out)")}else{$status.Text='Error - see pipeline.log';$queue.Text=('Build queue - error on {0}' -f $j.Name)};if($jobs.Count -gt 0){Start-NextJob}else{$build.Enabled=$true}}});$uiTimer.Start()
$jobs=New-Object System.Collections.Queue; $script:busy=$false
$worker=New-Object ComponentModel.BackgroundWorker
$worker.add_DoWork({ param($s,$e); $j=$e.Argument; try { $env:PATH=$root+';C:\Projects\Structure;C:\Projects\Img;C:\Projects\Background;'+$env:PATH; $logFile=Join-Path $j.Out 'pipeline.log';[IO.File]::WriteAllText($logFile,('[forge] started '+(Get-Date)+[Environment]::NewLine)); if($j.Type -eq 'image'){$outFile=Join-Path $j.Out ($j.Name+'.png');$psi=New-Object Diagnostics.ProcessStartInfo;$psi.FileName='cmd.exe';$psi.WorkingDirectory=$root;$psi.Arguments='/d /c generate.cmd "'+$j.Prompt+'" --out "'+$outFile+'"'}else{$glb=Join-Path $j.Out ($j.Name+'.glb');$psi=New-Object Diagnostics.ProcessStartInfo;$psi.FileName='cmd.exe';$psi.WorkingDirectory=$root;$psi.Arguments='/d /c forge.cmd --name '+$j.Name+' --resolution 512 --model trellis --out "'+$glb+'" "'+$j.Prompt+'"'};$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$false;$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$p=New-Object Diagnostics.Process;$p.StartInfo=$psi;$p.Start();$lines=New-Object Text.StringBuilder;while(($line=$p.StandardOutput.ReadLine()) -ne $null){[void]$lines.AppendLine($line);[IO.File]::AppendAllText($logFile,($line+[Environment]::NewLine))};$p.WaitForExit();$all=$lines.ToString();$e.Result=[pscustomobject]@{Job=$j;Code=$p.ExitCode;Output=$all} } catch { $all=('PROCESS ERROR: '+($_.Exception.ToString()));[IO.File]::AppendAllText((Join-Path $j.Out 'pipeline.log'),($all+[Environment]::NewLine));$e.Result=[pscustomobject]@{Job=$j;Code=1;Output=$all} } })
$worker.add_RunWorkerCompleted({ param($s,$e); $r=$e.Result; $log.AppendText($r.Output); if($r.Code -eq 0){$status.Text='Complete - image and 3D model ready';$queue.Text='JOB QUEUE - DONE '+$r.Job.Name;$chat.AppendText("`r`n`r`nSYSTEM`r`nComplete. Outputs: $($r.Job.Out)")}else{$status.Text='Error - see logs';$queue.Text='JOB QUEUE - ERROR '+$r.Job.Name}; $script:busy=$false; if($jobs.Count -gt 0){Start-NextJob}else{$build.Enabled=$true} })
$script:currentJobNumber=0
function Start-NextJob { if($script:busy -or $script:activeProcess -or $jobs.Count -eq 0){return}; $j=$jobs.Dequeue(); $script:busy=$true; $script:currentJobNumber=$script:completedJobs+1; $script:activeJob=$j; $script:activeLog=Join-Path $j.Out 'pipeline.log'; $script:logOffset=0; $progress.Style='Marquee';$progress.MarqueeAnimationSpeed=25;$status.Text=('Running job {0} of {1} - starting...' -f $script:currentJobNumber,$script:totalJobs); $queue.Text=('Build queue - running {0}/{1}; {2} waiting' -f $script:currentJobNumber,$script:totalJobs,$jobs.Count); $log.AppendText("Starting $($j.Type) workflow for $($j.Name)`r`n"); $psi=New-Object Diagnostics.ProcessStartInfo; $psi.FileName='cmd.exe'; $psi.WorkingDirectory=$root; if($j.Type -eq 'image'){$outFile=Join-Path $j.Out ($j.Name+'.png');$psi.Arguments='/d /c generate.cmd "'+$j.Prompt+'" --out "'+$outFile+'"'}else{$glb=Join-Path $j.Out ($j.Name+'.glb');$psi.Arguments='/d /c forge.cmd --name '+$j.Name+' --resolution 512 --model trellis --out "'+$glb+'" "'+$j.Prompt+'"'};$psi.UseShellExecute=$false;$psi.CreateNoWindow=$true;$script:activeProcess=New-Object Diagnostics.Process;$script:activeProcess.StartInfo=$psi;$script:activeProcess.Start()|Out-Null }
$build.Add_Click({ try { $raw=$promptBox.Text.Trim(); if(!$raw){return}; $isImage=$raw -match '^(generate|image)\b'; $type=if($isImage){'image'}else{'model'}; $namePrefix=if($isImage){'image'}else{'forge'}; $named=[regex]::Match($raw,'\bnamed\s+([A-Za-z0-9_-]+)',[Text.RegularExpressions.RegexOptions]::IgnoreCase); $stamp=Get-Date -Format 'yyyyMMdd_HHmmss_fff'; $name=if($named.Success){$named.Groups[1].Value+'_'+$stamp}else{$namePrefix+'_'+$stamp}; $prompt=$raw -replace '^(generate|image|forge)\s*','' -replace '\bnamed\s+[A-Za-z0-9_-]+',''; $out=Join-Path $root $name; New-Item -ItemType Directory -Force $out|Out-Null; $script:totalJobs++; $prelog=Join-Path $out 'pipeline.log'; [IO.File]::WriteAllText($prelog,('UI job created: '+$name+[Environment]::NewLine+'Prompt: '+$prompt+[Environment]::NewLine)); $status.Text=('Waiting for local prompt enhancement - job {0} of {1}' -f ($script:totalJobs),$script:totalJobs); $chat.AppendText("`r`n`r`nYOU`r`n$raw`r`n`r`nWORKFLOW - $type`r`n"); $enhanced=& $py $enhancer $prompt 2>$null; $enhanced=($enhanced|Out-String).Trim(); if(!$enhanced){$enhanced=$prompt+', clear silhouette, full body, clean topology, PBR materials, Unity-ready'}; [IO.File]::AppendAllText($prelog,('Enhanced prompt: '+$enhanced+[Environment]::NewLine)); $chat.AppendText("ENHANCED PROMPT`r`n$enhanced"); $status.Text='Prompt enhanced. Waiting for build slot...'; $jobs.Enqueue([pscustomobject]@{Name=$name;Out=$out;Prompt=$enhanced;Type=$type}); $queue.Text=('Build queue - {0} waiting' -f $jobs.Count); if(!$script:busy){Start-NextJob} } catch { $status.Text='Error - see ui-error.log'; $msg='UI HANDOFF ERROR: '+$_.Exception.ToString(); [IO.File]::AppendAllText((Join-Path $root 'ui-error.log'),("`r`n[$(Get-Date)] "+$msg+"`r`n")); if($out -and (Test-Path $out)){[IO.File]::AppendAllText((Join-Path $out 'pipeline.log'),($msg+'`r`n'))}; $log.AppendText($msg+'`r`n'); [Windows.Forms.MessageBox]::Show($msg,'Model Forge error','OK','Error') } })
$form.Add_Shown({$promptBox.Focus()});$form.ShowDialog()|Out-Null
